import {drawPreview} from './conquest-render.mjs';
const number=n=>Math.floor(n||0).toLocaleString('fr'),clock=n=>Math.floor(Math.max(0,n)/60)+':'+String(Math.floor(Math.max(0,n)%60)).padStart(2,'0');
const write=(el,text)=>{if(el&&el.textContent!==String(text))el.textContent=String(text)};
const ID=(c,id)=>c.g.modeRoot.querySelector('#'+id);
function setup(c){const g=c.g;if(!c.regions.length)return g.heading('STRATÉGIE EN TEMPS RÉEL','Conquête',c.loadError||'Chargement des régions…');const f=FACTION(c.settings.faction),guest=c.net.guest;return g.heading('STRATÉGIE EN TEMPS RÉEL','Conquête','Choisis ta team, pose ton QG et prends la région.')+`<section class="cq-quick-setup"><div class="cq-setup-map"><canvas width="690" height="470" data-conquest-preview="${c.settings.region}"></canvas><span>${g.escape(c.region().name)}</span><div class="cq-setup-map-caption">9 régions · 11 teams · solo ou entre amis</div></div><div class="cq-setup-form"><span class="eyebrow">TA PROCHAINE CAMPAGNE</span><label>Région<select id="cq-setup-region" ${guest?'disabled':''}>${c.regions.map(r=>`<option value="${r.id}" ${r.id===c.settings.region?'selected':''}>${g.escape(r.name)}</option>`).join('')}</select></label><label>Ta team<select id="cq-setup-faction">${FACTIONS.map(f=>`<option value="${f.id}" ${f.id===c.settings.faction?'selected':''}>${f.name}</option>`).join('')}</select></label><div class="cq-setup-legend"><img src="${Art.icon(String(f.legend))}" alt="${f.legendName}"><div><b>${f.legendName}</b><small>Le légendaire de ta team</small></div></div><label>Difficulté<select id="conq-difficulty" ${guest?'disabled':''}>${[[1,'Accessible'],[2,'Stratège'],[3,'Commandant']].map(([n,t])=>`<option value="${n}" ${+c.settings.difficulty===n?'selected':''}>${t}</option>`).join('')}</select></label><details class="cq-setup-more" ${c.setupMore?'open':''}><summary>Options de partie</summary><label>Adversaires IA<select id="conq-bots" ${guest?'disabled':''}>${[2,4,5,7,8].map(n=>`<option value="${n}" ${+c.settings.bots===n?'selected':''}>${n} teams IA</option>`).join('')}</select></label><label>Durée maximale<select id="conq-limit" ${guest?'disabled':''}>${[600,1200,1800].map(n=>`<option value="${n}" ${+c.settings.limit===n?'selected':''}>${n/60} min</option>`).join('')}</select></label><small>Neuf teams au maximum, joueurs compris. Objectif : 80 % des terres.</small></details>${c.saved&&c.saved.phase!=='finished'&&!c.net.peer?'<button class="primary" data-act="conq-resume">Reprendre ma campagne →</button>':''}<button class="${c.saved&&!c.net.peer?'':'primary'}" data-act="conq-start" ${guest?'disabled':''}>${c.net.peer?'Lancer le salon':'Jouer en solo'} ↗</button><button class="text-button" data-act="conq-help">Comment jouer ?</button></div></section><details class="cq-setup-friends panel" ${c.setupFriends||c.net.peer?'open':''}><summary>♧ Jouer avec des amis <small>Jusqu’à quatre joueurs</small></summary><div>${c.net.peer?`<p>${g.escape(c.net.status)}</p>${!guest&&c.net.peer.id?`<div class="room-code"><small>CODE DU SALON</small><strong>${g.escape(c.net.peer.id)}</strong><button data-act="conq-copy">Copier</button></div>`:''}<div class="conq-members">${c.net.members.map(m=>`<div><img src="${trainerSrc(m.avatar)}" alt=""><span><b>${g.escape(m.name)}</b><small>${FACTION(m.faction).name}</small></span></div>`).join('')}</div><button data-act="conq-room-close">Quitter le salon</button>`:`<button data-act="conq-create">Créer un salon</button><div class="conq-join"><input id="conq-code" placeholder="Code de ton ami" aria-label="Code du salon Conquête"><button data-act="conq-join">Rejoindre</button></div>${c.net.status?`<p>${g.escape(c.net.status)}</p>`:''}`}<small>Chaque ami doit avoir accès au site privé. L’hôte garde la partie ouverte.</small></div></details>`}
function afterSetup(c){if(c.g.page!=='conquest')return;for(const canvas of c.g.root.querySelectorAll('[data-conquest-preview]'))drawPreview(canvas,c.map(canvas.dataset.conquestPreview),FACTION(c.settings.faction).color);for(const field of['region','faction'])c.g.root.querySelector('#cq-setup-'+field)?.addEventListener('change',e=>c.action('conq-'+field,{[field]:e.target.value}));for(const key of['bots','difficulty','limit'])c.g.root.querySelector('#conq-'+key)?.addEventListener('change',e=>{c.settings[key]=+e.target.value;c.persistSettings();if(c.net.peer&&!c.net.guest)c.net.lobby()});c.g.root.querySelector('.cq-setup-more')?.addEventListener('toggle',e=>c.setupMore=e.target.open);c.g.root.querySelector('.cq-setup-friends')?.addEventListener('toggle',e=>c.setupFriends=e.target.open)}
export function conquestLayout(c){c.panelOpen=false;c.scoreOpen=false;c.logOpen=false;c.context=null;c.aim=null;c.pending=new Map();c.frontNodes=new Map();c.scoreNodes=new Map();c.pointerBusy=false;c.feedback=null;c.lastHUD=0;c.lastSync=0;c.focusedHQ=false;c.lastStep=performance.now();return `<div class="conquest-app cq-simple"><div class="conq-board"><div class="conq-viewport"><canvas id="conq-canvas" aria-label="Carte de Conquête : clic pour agir, clic droit pour les actions"></canvas><div class="cq-top-info"><span id="conq-mark"></span><div class="cq-team-info"><b id="conq-team-name"></b><small>CONQUÊTE · <span id="conq-region-name"></span> · <span id="cq-clock"></span></small></div><div class="cq-resources"><span>◒ <b id="cq-balls"></b><small id="cq-growth"></small></span><span>₽ <b id="cq-gold"></b><small id="cq-income"></small></span><span>⚑ <b id="cq-territory"></b><small>objectif 80 %</small></span></div></div><div class="cq-top-buttons"><button data-act="cq-score" aria-label="Classement">⚑ <span>Classement</span></button><button data-act="conq-help" aria-label="Aide">?</button><button data-act="conq-pause" id="cq-pause" aria-label="Pause">Ⅱ</button><button data-act="cq-options" aria-label="Menu de partie">⋯</button></div><div class="cq-score-card" id="cq-score" hidden><div class="cq-card-title">Classement<button data-act="cq-score" aria-label="Fermer le classement">×</button></div><div id="cq-ranking"></div></div><div id="cq-options" class="cq-options-card" hidden><button data-act="conq-home">⌂ Recentrer sur mon QG</button><button data-act="conq-fit">⊡ Voir toute la région</button><button data-act="cq-log">☷ Journal de la partie</button><button data-act="conq-help">? Aide</button><button data-act="conq-exit">↗ Quitter la campagne</button></div><div class="cq-orders" id="cq-orders" aria-label="Attaques en cours"></div><div class="cq-log-card" id="cq-log" hidden><div class="cq-card-title">Radio de la team<button data-act="cq-log" aria-label="Fermer le journal">×</button></div><div id="cq-journal"></div></div><div class="cq-context" id="cq-context" role="dialog" aria-label="Actions de la zone" hidden></div><div class="cq-feedback" id="cq-feedback" role="status" aria-live="polite" hidden></div><div class="conq-tooltip" id="cq-tooltip" hidden></div><div class="conq-map-controls"><button data-act="conq-zoom" data-factor="1.25" aria-label="Zoom avant">+</button><button data-act="conq-zoom" data-factor="0.8" aria-label="Zoom arrière">−</button><button data-act="conq-fit" aria-label="Voir toute la région">⊡</button></div><canvas class="conq-minimap" id="conq-minimap" width="190" height="124" aria-label="Mini-carte"></canvas><div class="cq-reserve"><div><strong>Force engagée</strong><span><b id="cq-fraction-label">30 %</b> · <b id="cq-commit-label"></b></span></div><input id="cq-fraction" type="range" min="5" max="100" step="5" value="30" aria-label="Pourcentage de Poké Balls engagées"><small>Garde une réserve pour défendre ta team.</small></div><div class="conq-notice" id="cq-notice"></div><div class="cq-target-banner" id="cq-target" hidden><span></span><button data-act="cq-cancel">Annuler · Échap</button></div><div class="conq-pause-overlay" id="cq-pause-overlay" hidden><span class="eyebrow">OPÉRATION EN PAUSE</span><h2>À toi de reprendre.</h2><p id="cq-pause-message"></p><button class="primary" data-act="conq-pause" id="cq-resume">Reprendre</button></div><div class="conq-end-overlay" id="cq-end" hidden></div></div></div></div>`}
function cancel(c){c.context=null;c.aim=null;c.tool='attack';ID(c,'cq-context').hidden=true;ID(c,'cq-target').hidden=true;c.canvas.style.cursor='default'}
function closeContext(c){c.context=null;ID(c,'cq-context').hidden=true}
function anchor(c,cell){const p=c.renderer.screen(point(cell));const el=ID(c,'cq-context'),half=el.classList.contains('cq-wheel')?152:156,height=el.offsetHeight||300;const x=clamp(p.x,half+8,Math.max(half+8,c.renderer.width-half-8)),y=clamp(p.y,height/2+12,Math.max(height/2+12,c.renderer.height-height/2-110));el.style.left=x+'px';el.style.top=y+'px'}
function button(action,icon,label,extra='',attrs=''){return `<button data-act="cq-context-action" data-command="${action}" ${attrs}><i>${icon}</i><b>${label}</b><small data-detail>${extra}</small></button>`}
function openContext(c,cell,page='auto'){if(c.s.phase!=='playing'||c.s.paused)return;c.aim=null;c.tool='attack';c.selected=cell;const s=c.s,id=c.me.id,owner=s.owners[cell],b=s.buildings.find(b=>b.cell===cell);if(page==='auto')page=b&&owner===id?'building':owner===id?'build':'main';c.scoreOpen=false;c.logOpen=false;ID(c,'cq-score').hidden=true;ID(c,'cq-log').hidden=true;ID(c,'cq-options').hidden=true;c.context={cell,page,building:b?.id,owner};const el=ID(c,'cq-context');ID(c,'cq-tooltip').hidden=true;el.hidden=false;el.className='cq-context';const close='<button class="cq-context-close" data-act="cq-close" aria-label="Fermer les actions">×</button>';
 if(page==='build'){el.classList.add('cq-wheel');el.innerHTML=`<div class="cq-wheel-title">Construire ici</div><div class="cq-wheel-actions">${BUILDINGS.map((def,i)=>button('build',def.icon,def.id==='factory'?'Usine de Balls':def.id==='shield'?'Gardevoir':def.id==='shrine'?'Sanctuaire':def.name,'',`data-building="${def.id}" style="--angle:${i*60-90}deg;--reverse:${90-i*60}deg"`)).join('')}</div><button class="cq-wheel-center" data-act="cq-close" aria-label="Annuler la construction">×<small>Fermer</small></button><div class="cq-context-status" data-status></div>`}
 else if(page==='building'){el.innerHTML=`${close}<span class="eyebrow">TON BÂTIMENT</span><h3>${BUILDING(b.kind).name}</h3><p>${BUILDING(b.kind).desc}</p><div class="cq-building-level" data-level></div>${button('upgrade','↑','Améliorer','','data-building-id="'+b.id+'"')}<div class="cq-context-status" data-status></div>`}
 else if(page==='legend'){el.innerHTML=`${close}<div class="cq-context-legend"><img src="${Art.icon(String(FACTION(c.me.faction).legend))}" alt=""><div><span class="eyebrow">FRAPPER CETTE ZONE</span><h3>${FACTION(c.me.faction).legendName}</h3></div></div>${STRIKES.map(t=>button('legend','✧',t.name,'',`data-tier="${t.id}"`)).join('')}<div class="cq-context-status" data-status></div>`}
 else if(page==='diplomacy'){const other=player(s,owner);if(!other){closeContext(c);return}el.innerHTML=`${close}<span class="eyebrow">${c.g.escape(other.name)}</span><h3>${FACTION(other.faction).name}</h3><p data-relation></p>${button('alliance','♧','Proposer un pacte')}${button('donate-credits','₽','Donner 20 % des fonds')}${button('donate-balls','◒','Donner 20 % des Poké Balls')}${button('embargo','⊘','Basculer l’embargo')}${button('betray','⚔','Rompre le pacte')}<div class="cq-context-status" data-status></div>`}
 else if(page==='ship'){const ship=s.missions.find(m=>m.id===c.ship);el.innerHTML=`${close}<span class="eyebrow">TA PATROUILLE</span><h3>Léviator</h3><p>Niveau ${ship?.level||1} · ${number(ship?.hp)} PV</p>${button('move-ship','➜','Déplacer la patrouille')}${button('ping','⚑','Signaler cette position')}<div class="cq-context-status" data-status></div>`}
 else{el.classList.add('cq-wheel');const other=player(s,owner),friendly=other&&allied(s,id,owner);const actions=[['attack',friendly?'◒':'⚔',friendly?'Envoyer des renforts':'Attaquer'],['build','▥','Construire'],['transport','≈','Lokhlass'],['legend-menu','✧','Légendaire'],['diplomacy-menu','♧','Diplomatie'],['patrol','♞','Léviator']];el.innerHTML=`<div class="cq-wheel-title">${other?FACTION(other.faction).name:!s.map.terrain[cell]?'Zone maritime':'Terre neutre'}</div><div class="cq-wheel-actions">${actions.map(([a,i,t],n)=>button(a,i,t,'',`style="--angle:${n*60-90}deg;--reverse:${90-n*60}deg"`)).join('')}</div><button class="cq-wheel-center" data-act="cq-close" aria-label="Fermer les actions">×<small>Fermer</small></button><div class="cq-context-status" data-status></div>`}
 refreshContext(c);anchor(c,cell);el.querySelector('[data-act="cq-close"]')?.focus({preventScroll:true})}
function availability(c,button){const s=c.s,me=c.me,ctx=c.context,cell=ctx.cell,own=s.owners[cell]===me.id,owner=player(s,s.owners[cell]),ally=owner&&allied(s,me.id,owner.id),action=button.dataset.command,building=s.buildings.find(b=>b.cell===cell);const no=message=>({ok:false,message}),yes=(message='')=>({ok:true,message});if(s.paused)return no('Partie en pause');if(!me.alive)return no('Ta team est éliminée');
 if(action==='build'){if(!own)return no('Sur ton territoire');if(building)return no('Case déjà occupée');const kind=button.dataset.building;if(!kind)return yes('Ouvrir les constructions');const def=BUILDING(kind),cost=buildCost(s,me.id,kind);if(s.burn[cell]>s.time)return no('Zone perturbée');if(def.coast&&!coastCells(s,cell).length)return no('Près de l’eau uniquement');return me.credits>=cost?yes(number(cost)+' ₽'):no(number(cost)+' ₽ · fonds insuffisants')}
 if(action==='upgrade'){const b=s.buildings.find(b=>b.id===+button.dataset.buildingId);if(!b||b.owner!==me.id)return no('Bâtiment indisponible');if(!ready(s,b))return no('Prêt dans '+Math.ceil(b.complete-s.time)+' s');if(b.level>=3)return no('Niveau maximum');const cost=Math.round(BUILDING(b.kind).cost*b.level*.8);return me.credits>=cost?yes(number(cost)+' ₽ · niv. '+(b.level+1)):no(number(cost)+' ₽ · fonds insuffisants')}
 if(action==='legend-menu'||action==='legend'){if(!s.map.terrain[cell]||own||ally)return no('Sur une terre adverse');const tier=STRIKE(button.dataset.tier||'signature'),shrines=aliveBuildings(s,me.id,'shrine').filter(b=>b.level>=tier.level);if(!shrines.length)return no('Sanctuaire niv. '+tier.level+' requis');if(!shrines.some(b=>b.readyAt<=s.time))return no('Recharge · '+Math.ceil(Math.min(...shrines.map(b=>b.readyAt))-s.time)+' s');if(action==='legend-menu')return yes('Choisir la puissance');if(tier.id==='constellation'&&!owner)return no('Cible une team');return me.credits>=tier.cost?yes(number(tier.cost)+' ₽'):no(number(tier.cost)+' ₽ · fonds insuffisants')}
 if(action==='attack'){if(!s.map.terrain[cell]||own)return no('Cible une autre zone');if(ally)return me.balls>=50?yes('Donner 20 %'):no('Réserve insuffisante');if(!frontier(s,me.id,s.owners[cell],s.map.landComponents[cell]).length)return no('Pas de frontière commune');return me.balls*c.fraction>=12?yes(number(me.balls*c.fraction)+' Poké Balls'):no('Réserve insuffisante')}
 if(action==='transport'){if(!s.map.terrain[cell]||own||ally)return no('Cible une côte adverse');if(!aliveBuildings(s,me.id,'port').length)return no('Base maritime requise');return me.balls*c.fraction>=25?yes(number(me.balls*c.fraction)+' Poké Balls'):no('25 Poké Balls minimum')}
 if(action==='patrol'){if(s.map.terrain[cell])return no('Sur la mer uniquement');if(!aliveBuildings(s,me.id,'port').length)return no('Base maritime requise');return me.credits>=600?yes('600 ₽'):no('600 ₽ · fonds insuffisants')}
 if(action==='diplomacy-menu')return owner&&owner.id!==me.id?yes('Pactes et échanges'):no('Choisis une autre team');
 if(['alliance','donate-credits','donate-balls','embargo','betray'].includes(action)){if(!owner||owner.id===me.id)return no('Choisis une autre team');if(action==='alliance')return ally?no('Pacte déjà actif'):yes('Protection réciproque');if(action==='betray')return ally?yes('Défense affaiblie 45 s'):no('Aucun pacte');return yes()}
 return yes()}
function refreshContext(c){if(!c.context)return;const el=ID(c,'cq-context');for(const b of el.querySelectorAll('[data-command]')){const state=availability(c,b);b.disabled=!state.ok;b.title=state.message;b.setAttribute('aria-disabled',String(!state.ok));write(b.querySelector('[data-detail]'),state.message)}const built=c.s.buildings.find(b=>b.id===c.context.building);if(built)write(el.querySelector('[data-level]'),'Niveau '+built.level+' / 3'+(!ready(c.s,built)?' · Construction '+Math.ceil(built.complete-c.s.time)+' s':''));const owner=player(c.s,c.s.owners[c.context.cell]);if(owner)write(el.querySelector('[data-relation]'),(allied(c.s,c.me.id,owner.id)?'Pacte actif':'Aucun pacte')+' · '+(embargoed(c.s,c.me.id,owner.id)?'Commerce bloqué':'Commerce autorisé'));write(el.querySelector('[data-status]'),'Les actions grisées indiquent ce qui manque.');}
function landing(c,cell){const s=c.s,id=c.me.id,owner=s.owners[cell],component=s.map.landComponents[cell],seas=new Set(aliveBuildings(s,id,'port').flatMap(b=>coastCells(s,b.cell).map(i=>s.map.water[i])));if(!seas.size)return null;const connected=i=>coastCells(s,i).some(w=>seas.has(s.map.water[w]));if(connected(cell))return cell;let best=null,distance=Infinity;const focus=point(cell);for(let i=0;i<s.map.terrain.length;i++)if(s.map.terrain[i]&&s.owners[i]===owner&&s.map.landComponents[i]===component&&connected(i)){const d=dist(focus,point(i));if(d<distance){best=i;distance=d}}return best}
function at(c,cell){if(!c.active||c.s.phase==='finished')return;c.selected=cell;if(c.s.phase==='placement'){c.send({kind:'spawn',cell});return}if(c.s.paused)return;closeContext(c);const aim=c.aim;c.aim=null;c.tool='attack';if(aim){if(aim.kind==='legend'){openContext(c,cell,'legend');return}if(aim.kind==='build'){openContext(c,cell,'build');return}if(aim.kind==='move-ship'){c.send({kind:'patrol',cell,shipId:aim.ship});return}}const owner=c.s.owners[cell];if(owner===c.me.id){openContext(c,cell);return}if(owner>0&&allied(c.s,c.me.id,owner)){openContext(c,cell,'diplomacy');return}if(!c.s.map.terrain[cell]){openContext(c,cell);return}if(frontier(c.s,c.me.id,owner,c.s.map.landComponents[cell]).length){c.send({kind:'attack',cell,fraction:c.fraction});return}const shore=landing(c,cell);if(shore!==null){c.send({kind:'transport',cell:shore,fraction:c.fraction});return}openContext(c,cell);feedback(c,{kind:'attack',cell},'info','Pas de frontière commune. Choisis une action.');c.hud()}
function hit(c,p,snap=true){const world=c.renderer.world(p.x,p.y);if(world.x<0||world.x>=W||world.y<0||world.y>=H)return null;const exact=index(world.x,world.y);if(c.s.phase==='placement'||!snap||c.aim?.kind==='build')return exact;const building=c.s.buildings.find(b=>b.cell===exact);if(building)return exact;let best=null,d=10;for(const b of c.s.buildings){const pos=c.renderer.screen(point(b.cell)),delta=Math.hypot(pos.x-p.x,pos.y-p.y);if(delta<d){d=delta;best=b.cell}}return best??exact}
function bind(c){const signal=c.abort.signal,canvas=c.canvas,local=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};const clearHold=()=>{clearTimeout(c.holdTimer);c.holdTimer=null};canvas.addEventListener('contextmenu',e=>{e.preventDefault();clearHold();if(c.aim){cancel(c);c.hud();return}const cell=hit(c,local(e));if(cell!==null){if(c.context?.cell===cell)closeContext(c);else openContext(c,cell)}},{signal});canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;c.scoreOpen=false;c.logOpen=false;ID(c,'cq-options').hidden=true;canvas.setPointerCapture(e.pointerId);const p=local(e);c.points.set(e.pointerId,p);if(c.points.size===1){c.multiGesture=false;c.drag={id:e.pointerId,start:p,last:p,moved:false,long:false};if(e.pointerType==='touch'){c.holdTimer=setTimeout(()=>{if(c.drag&&!c.drag.moved&&!c.multiGesture){c.drag.long=true;c.drag.moved=true;const cell=hit(c,p);if(cell!==null)openContext(c,cell)}},750)}}else{clearHold();c.multiGesture=true;const points=[...c.points.values()];c.pinch=Math.hypot(points[0].x-points[1].x,points[0].y-points[1].y);if(c.drag)c.drag.moved=true}},{signal});canvas.addEventListener('pointermove',e=>{const p=local(e);c.hover=hit(c,p,false);if(c.points.has(e.pointerId)){c.points.set(e.pointerId,p);if(c.points.size===2){clearHold();const values=[...c.points.values()],d=Math.hypot(values[0].x-values[1].x,values[0].y-values[1].y);if(c.pinch)c.renderer.zoom(d/c.pinch,(values[0].x+values[1].x)/2,(values[0].y+values[1].y)/2);c.pinch=d;closeContext(c)}else if(c.drag?.id===e.pointerId){if(Math.hypot(p.x-c.drag.start.x,p.y-c.drag.start.y)>10){clearHold();c.drag.moved=true}if(c.drag.moved&&!c.drag.long){closeContext(c);c.renderer.cam.x+=p.x-c.drag.last.x;c.renderer.cam.y+=p.y-c.drag.last.y}c.drag.last=p}}c.tooltip(p)},{signal});const end=(e,cancelled=false)=>{if(e.button>0)return;clearHold();if(!cancelled&&c.drag?.id===e.pointerId&&!c.drag.moved&&!c.multiGesture&&c.points.size===1){const p=local(e),cell=hit(c,p);if(cell!==null){if(e.ctrlKey)openContext(c,cell,'build');else{let ship;for(const m of c.s.missions.filter(m=>m.kind==='patrol'&&m.owner===c.me.id)){const a=c.renderer.screen(missionPosition(m));if(Math.hypot(a.x-p.x,a.y-p.y)<14){ship=m;break}}if(ship&&!c.aim){c.ship=ship.id;openContext(c,cell,'ship')}else at(c,cell)}}else cancel(c)}c.points.delete(e.pointerId);c.pinch=null;if(c.points.size===1&&c.multiGesture){const [id,last]=[...c.points.entries()][0];c.drag={id,start:last,last,moved:true,long:false}}if(!c.points.size){c.drag=null;c.multiGesture=false}};canvas.addEventListener('pointerup',e=>end(e),{signal});canvas.addEventListener('pointercancel',e=>end(e,true),{signal});canvas.addEventListener('wheel',e=>{e.preventDefault();closeContext(c);const p=local(e);c.renderer.zoom(Math.exp(clamp(-e.deltaY*.0015,-.35,.35)),p.x,p.y)},{signal,passive:false});c.g.modeRoot.addEventListener('pointerdown',()=>c.pointerBusy=true,{signal,capture:true});const release=()=>setTimeout(()=>{if(c.active){c.pointerBusy=false;c.hud()}},0);document.addEventListener('pointerup',release,{signal,capture:true});document.addEventListener('pointercancel',release,{signal,capture:true});ID(c,'cq-fraction').addEventListener('input',e=>{c.fraction=+e.target.value/100;c.hud()},{signal});ID(c,'conq-minimap').addEventListener('pointerdown',e=>{const r=e.currentTarget.getBoundingClientRect();closeContext(c);c.renderer.center(index(clamp((e.clientX-r.left)/r.width*W,0,W-1),clamp((e.clientY-r.top)/r.height*H,0,H-1)))},{signal});}
function feedback(c,cmd,tone,text,seq=null){const cell=Number.isInteger(cmd.cell)?cmd.cell:c.s.buildings.find(b=>b.id===cmd.buildingId)?.cell??c.selected??c.me.home;if(cell===null||cell===undefined)return;c.feedback={cell,tone,text,at:performance.now(),seq};const el=ID(c,'cq-feedback');el.hidden=false;el.dataset.tone=tone;write(el,text);const p=c.renderer.screen(point(cell));el.style.left=clamp(p.x,100,c.renderer.width-100)+'px';el.style.top=clamp(p.y-34,90,c.renderer.height-150)+'px'}
function orderText(c,cmd,result){const f=FACTION(c.me.faction);if(!result.ok)return result.message;return({spawn:'QG installé',attack:result.reinforced?'Front renforcé':'Escouade envoyée',transport:'Lokhlass en route',patrol:cmd.shipId?'Patrouille redirigée':'Léviator déployé',build:'Construction lancée',upgrade:'Amélioration lancée',legend:f.legendName+' en route !',retreat:'Escouade rappelée',diplomacy:result.message||'Ordre diplomatique transmis',ping:'Position signalée'})[cmd.kind]||'Ordre reçu'}
function send(c,cmd){if(c.net.guest){const seq=c.net.send(cmd);if(!Number.isInteger(seq)){feedback(c,cmd,'error','Connexion indisponible');return{ok:false}}c.pending.set(seq,{command:cmd,at:performance.now()});feedback(c,cmd,'pending','Ordre envoyé…',seq);closeContext(c);c.hud();return{ok:true,pending:true}}const result=c.issue(cmd,c.me.id);feedback(c,cmd,result.ok?'success':'error',orderText(c,cmd,result));if(result.ok){closeContext(c);c.aim=null;c.tool='attack'}else c.g.toast(result.message);c.hud();return result}
function issue(c,cmd,id){const result=command(c.s,id,cmd);if(result.ok){c.hud();if(id===c.me.id)c.g.audio.tone(cmd.kind==='legend'?160:410,.05,.012)}return result}
function acknowledge(c,seq,result){const pending=c.pending.get(seq);if(!pending)return;c.pending.delete(seq);if(c.feedback?.seq===seq)feedback(c,pending.command,result.ok?'success':'error',orderText(c,pending.command,result),seq);if(!result.ok)c.g.toast(result.message);c.hud()}
function tick(c){if(!c.active)return;const now=performance.now();if(!c.net.guest){step(c.s,.05);c.lastStep=now;if(!c.net.peer&&c.s.phase==='playing'&&!c.me.alive){c.s.phase='finished';c.s.winners=[]}if(now-(c.lastSync||0)>=200){c.lastSync=now;c.net.sync()}if(c.s.phase==='finished')c.finish();if(now-c.lastSave>6000){c.saveRun();c.lastSave=now}}if(now-(c.lastHUD||0)>=100){c.lastHUD=now;c.hud()}}
function hud(c){if(!c.active)return;const s=c.s,me=c.me,f=FACTION(me.faction),root=c.g.modeRoot;if(c.renderer&&c.renderer.width<650&&me.deployed&&!c.focusedHQ){c.focusedHQ=true;c.renderer.zoom(Math.max(1,7/c.renderer.cam.scale));c.renderer.center(me.home)}for(const [id,value]of Object.entries({'conq-mark':f.mark,'conq-team-name':f.name,'conq-region-name':s.map.name,'cq-clock':clock(s.time-s.startedAt),'cq-balls':number(me.balls)+' / '+number(me.cap),'cq-growth':'+'+number(me.growth)+'/s','cq-gold':number(me.credits),'cq-income':'+'+number(me.income)+'/s','cq-territory':(me.land/s.map.land*100).toFixed(1)+' %','cq-fraction-label':Math.round(c.fraction*100)+' %','cq-commit-label':number(me.balls*c.fraction)+' Balls'}))write(ID(c,id),value);ID(c,'conq-mark').style.color=f.color;ID(c,'cq-score').hidden=!c.scoreOpen;ID(c,'cq-log').hidden=!c.logOpen;ID(c,'cq-target').hidden=!c.aim;write(ID(c,'cq-target').querySelector('span'),c.aim?.kind==='legend'?'Choisis la zone à frapper':c.aim?.kind==='move-ship'?'Choisis la nouvelle zone de patrouille':'Choisis une de tes cases pour construire');c.canvas.style.cursor=c.aim?'crosshair':'default';ID(c,'cq-pause-overlay').hidden=!s.paused||s.phase==='finished';ID(c,'cq-pause').disabled=c.net.guest||c.disconnected;ID(c,'cq-resume').hidden=c.net.guest||c.disconnected;write(ID(c,'cq-pause-message'),c.disconnected?'La connexion à l’hôte a été perdue.':c.net.guest?'L’hôte a mis la partie en pause.':'La campagne reprendra quand tu seras prêt.');write(ID(c,'cq-notice'),s.phase==='placement'?(me.deployed?'En attente des autres QG…':'Clique une terre pour placer ton QG · '+Math.max(0,20-Math.floor(s.time))+' s'):c.disconnected?'Connexion perdue.':c.aim?'':c.context?'':c.s.time-c.s.startedAt<15?'Clic gauche : agir · Clic droit / appui long : actions':'');ID(c,'cq-notice').hidden=!ID(c,'cq-notice').textContent;
 const score=ID(c,'cq-ranking');for(const p of s.players){let row=c.scoreNodes.get(p.id);if(!row){row=document.createElement('button');row.dataset.act='conq-target';row.dataset.player=p.id;row.innerHTML='<i></i><span><b></b><small></small></span><strong></strong>';c.scoreNodes.set(p.id,row);score.append(row)}const faction=FACTION(p.faction);row.style.setProperty('--faction',faction.color);row.classList.toggle('mine',p.id===me.id);write(row.querySelector('i'),faction.mark);write(row.querySelector('b'),faction.name);write(row.querySelector('small'),p.name+(p.ai?' · IA':'')+(!p.alive?' · Éliminée':''));write(row.querySelector('strong'),(p.land/s.map.land*100).toFixed(1)+' %')}if(!c.pointerBusy){const order=s.players.slice().sort((a,b)=>b.land-a.land).map(p=>p.id);if(order.join(',')!==c.rankOrder){for(const id of order)score.append(c.scoreNodes.get(id));c.rankOrder=order.join(',')}}
 const fronts=s.orders.filter(o=>o.owner===me.id),container=ID(c,'cq-orders');for(const o of fronts){let row=c.frontNodes.get(o.id);if(!row){row=document.createElement('div');row.className='cq-active-order';row.innerHTML=`<i>⚔</i><span><b></b><small></small></span><button data-act="conq-retreat" data-order="${o.id}" title="Rappeler l’escouade" aria-label="Rappeler l’escouade">×</button>`;c.frontNodes.set(o.id,row);container.append(row)}write(row.querySelector('b'),o.target?FACTION(player(s,o.target).faction).name:'Expansion');write(row.querySelector('small'),number(o.left)+' Poké Balls')}if(!c.pointerBusy)for(const [id,node]of c.frontNodes)if(!fronts.some(o=>o.id===id)){node.remove();c.frontNodes.delete(id)}container.hidden=!fronts.length;
 const logs=s.log.slice(-5).reverse(),key=logs.map(e=>e.id).join(',');if(c.logOpen&&key!==c.lastLog&&!c.pointerBusy){ID(c,'cq-journal').innerHTML=logs.map(e=>`<p><time>${clock(e.time-s.startedAt)}</time>${c.g.escape(e.text)}</p>`).join('');c.lastLog=key}refreshContext(c);if(c.feedback&&performance.now()-c.feedback.at>(c.feedback.tone==='pending'?3500:1800)){ID(c,'cq-feedback').hidden=true;if(c.feedback.tone!=='pending')c.feedback=null}}
function tooltip(c,p){const el=ID(c,'cq-tooltip');if(c.hover===null||c.context||c.drag?.moved){el.hidden=true;return}const cell=c.hover,b=c.s.buildings.find(b=>b.cell===cell),owner=player(c.s,c.s.owners[cell]);el.hidden=false;write(el,b?BUILDING(b.kind).name+' · Niv. '+b.level:owner?FACTION(owner.faction).name:!c.s.map.terrain[cell]?'Mer':'Terre neutre');el.style.left=clamp(p.x+14,5,c.renderer.width-170)+'px';el.style.top=clamp(p.y+14,5,c.renderer.height-32)+'px'}
function help(c){const old=c.active&&!c.net.peer?c.s.paused:null;if(old!==null)c.s.paused=true;c.g.openModal(`<div class="conq-help"><span class="eyebrow">TROIS GESTES POUR JOUER</span><h2>La carte fait tout.</h2><ol><li><b>Clique une terre.</b> Ta team conquiert le terrain. Si la mer te sépare de la cible, Lokhlass est envoyé depuis une base maritime disponible.</li><li><b>Clique chez toi pour construire.</b> Choisis un bâtiment dans la roue. Clique un bâtiment existant pour l’améliorer.</li><li><b>Clic droit ou appui long.</b> Le menu propose les actions de la zone : légendaire, diplomatie, débarquement ou patrouille.</li></ol><p>Le curseur en bas fixe la force envoyée. Tes escouades actives apparaissent à gauche : × les rappelle. L’objectif reste de contrôler 80 % de la région.</p><p>Glisse pour déplacer la carte, utilise la molette ou deux doigts pour zoomer. Échap ferme d’abord les actions ouvertes. Ctrl+clic : constructions · N : viser avec un légendaire · B : choisir un emplacement.</p><details><summary>Économie et diplomatie</summary><p>Repaires : réserve accrue. Usines : Poké Balls et convois. Bases maritimes : commerce et navigation. Bastions : défense. Sanctuaires : trois niveaux d’assaut. Gardevoir : interception. Les pactes durent trois minutes ; les dons et embargos sont dans le menu d’une team.</p></details><button class="primary" data-act="close-modal">Jouer</button></div>`,{className:'conquest-help-dialog',onClose:()=>{if(old!==null&&c.active)c.s.paused=old}})}
function key(c,e){if(!c.active||c.g.modal.open||e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;const k=e.key.toLowerCase();if(k==='escape'){e.preventDefault();if(c.context||c.aim){cancel(c);c.hud()}else c.action('conq-pause',{});return}if(k===' '&&e.target instanceof HTMLButtonElement)return;if(k===' '){e.preventDefault();c.action('conq-pause',{});return}if(k==='n'||k==='b'){closeContext(c);c.aim={kind:k==='n'?'legend':'build'};c.tool=k==='n'?'legend':'attack';c.hud()}if(k==='r')for(const o of c.s.orders.filter(o=>o.owner===c.me.id))c.send({kind:'retreat',orderId:o.id});if(k==='+')c.renderer.zoom(1.2);if(k==='-')c.renderer.zoom(.8)}
function gameAction(c,act,d){if(!c.active)return false;if(act==='cq-close'){closeContext(c);return true}if(act==='cq-cancel'){cancel(c);c.hud();return true}if(act==='cq-score'||act==='conq-panel'){closeContext(c);ID(c,'cq-options').hidden=true;c.scoreOpen=!c.scoreOpen;c.hud();return true}if(act==='cq-log'){c.logOpen=!c.logOpen;ID(c,'cq-options').hidden=true;c.hud();return true}if(act==='cq-options'){closeContext(c);c.scoreOpen=false;c.logOpen=false;ID(c,'cq-score').hidden=true;ID(c,'cq-log').hidden=true;ID(c,'cq-options').hidden=!ID(c,'cq-options').hidden;return true}if(act==='conq-target'){const p=player(c.s,+d.player);if(p&&p.id!==c.me.id){let cell=p.home;if(c.s.owners[cell]!==p.id)cell=c.s.owners.findIndex(o=>o===p.id);if(cell>=0)openContext(c,cell,'diplomacy')}return true}if(act==='cq-context-action'){const ctx=c.context;if(!ctx)return true;const cell=ctx.cell,owner=c.s.owners[cell];if(d.command==='legend-menu'){openContext(c,cell,'legend');return true}if(d.command==='diplomacy-menu'){openContext(c,cell,'diplomacy');return true}if(d.command==='build'&&!d.building){openContext(c,cell,'build');return true}if(d.command==='move-ship'){closeContext(c);c.aim={kind:'move-ship',ship:c.ship};c.hud();return true}let cmd;if(d.command==='build')cmd={kind:'build',cell,building:d.building};if(d.command==='upgrade')cmd={kind:'upgrade',buildingId:+d.buildingId};if(d.command==='legend')cmd={kind:'legend',cell,tier:d.tier};if(d.command==='attack')cmd=owner>0&&allied(c.s,c.me.id,owner)?{kind:'diplomacy',other:owner,action:'donate',resource:'balls'}:{kind:'attack',cell,fraction:c.fraction};if(d.command==='transport'){const shore=landing(c,cell);if(shore===null){feedback(c,{cell},'error','Aucune côte reliée à ta base maritime');return true}cmd={kind:'transport',cell:shore,fraction:c.fraction}}if(d.command==='patrol')cmd={kind:'patrol',cell};if(d.command==='ping')cmd={kind:'ping',cell};if(['alliance','embargo','betray','donate-credits','donate-balls'].includes(d.command))cmd={kind:'diplomacy',other:owner,action:d.command.startsWith('donate')?'donate':d.command,resource:d.command==='donate-balls'?'balls':'credits'};if(cmd)c.send(cmd);return true}if(act==='conq-retreat'){c.send({kind:'retreat',orderId:+d.order});return true}if(act==='conq-tool'){if(d.tool==='legend'){closeContext(c);c.aim={kind:'legend'};c.tool='legend'}else if(d.tool==='build'){closeContext(c);c.aim={kind:'build'}}else cancel(c);c.hud();return true}if(act==='conq-pause'){cancel(c);ID(c,'cq-options').hidden=true;return false}if(['conq-home','conq-fit','conq-zoom'].includes(act)){closeContext(c);ID(c,'cq-options').hidden=true;return false}return false}
export function installConquestControls(Type){const p=Type.prototype,legacy=p.action,stop=p.stop;p.render=function(){return setup(this)};p.afterRender=function(){return afterSetup(this)};p.bindMap=function(){return bind(this)};p.tooltip=function(v){return tooltip(this,v)};p.click=function(cell){return at(this,cell)};p.send=function(cmd){return send(this,cmd)};p.issue=function(cmd,id){return issue(this,cmd,id)};p.acknowledge=function(seq,result){return acknowledge(this,seq,result)};p.tick=function(){return tick(this)};p.hud=function(){return hud(this)};p.key=function(e){return key(this,e)};p.help=function(){return help(this)};p.action=async function(act,d){if(gameAction(this,act,d))return;return legacy.call(this,act,d)};p.stop=function(){clearTimeout(this.holdTimer);this.pending?.clear();return stop.call(this)}}
